                                if (player.countCards('h') > 0) {
                                    list.push('手牌区');
                                }
                                if (player.countCards('e') > 0) {
                                    list.push('装备区');
                                }
                                if (player.countCards('j') > 0) {
                                    list.push('判定区');
                                }
                                if (player.countCards('hej') >= 0) {
                                    list.push('取消');
                                }
                                if (list.length) {
                                    player
                                        .chooseControl(list, function (event, player) {
                                            if (player.hasJudge('lebu') || player.hasJudge('bingliang')) return '判定区';
                                            if (player.countCards('e') > 1) return '装备区';
                                            if (player.countCards('h') > 0) return '手牌区';
                                            return '取消';
                                        })
                                        .set('prompt', '天剑:选择自身的一个区域并弃置该区域内的一张牌');
                                }
                                ('step 1');
                                if (result.control == '判定区') {
                                    player.chooseToDiscard(true, 'j');
                                    player.loseHp();
                                    event.goto(2);
                                } else if (result.control == '装备区') {
                                    player.chooseToDiscard(true, 'e');
                                    player.draw(2);
                                    event.goto(2);
                                } else if (result.control == '手牌区') {
                                    player.chooseToDiscard(true, 'h');
                                    player.draw();
                                    event.goto(2);
                                } else if (result.control == '取消') {
                                    event.finish();
                                }
                                ('step 2');
                                player
                                    .chooseTarget(get.prompt2('yh_tianjian'), '视为对一名角色使用杀', function (card, player, target) {
                                        return target != player;
                                    })
                                    .set('ai', function (target) {
                                        return get.attitude(player, target) < 0;
                                    });
                                ('step 3');
                                if (result.bool) {
                                    var target = result.targets[0];
                                    event.target = target;
                                    var card = { name: 'sha' };
                                    if (player.canUse(card, target, false)) player.useCard(card, target, false).card.yh_tianjian = true;
                                } else event.finish();
